import{_ as a,c as e,a2 as d,o as r}from"./chunks/framework.Bzjhwp8w.js";const o="/dllm/assets/e298c2828964408a3f7c1ee2e37d1d17.BZAxja-9.png",p=JSON.parse('{"title":"在 Langflow 中处理组件","description":"在 Langflow 中处理组件","frontmatter":{"title":"在 Langflow 中处理组件","description":"在 Langflow 中处理组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-processing.md","filePath":"langflow/components-processing.md"}'),h={name:"langflow/components-processing.md"};function l(n,t,s,i,b,u){return r(),e("div",null,t[0]||(t[0]=[d('<h1 id="在-langflow-中处理组件" tabindex="-1">在 Langflow 中处理组件 <a class="header-anchor" href="#在-langflow-中处理组件" aria-label="Permalink to &quot;在 Langflow 中处理组件&quot;">​</a></h1><p>处理组件在流程中处理和转换数据。</p><h2 id="在流程中使用处理组件" tabindex="-1">在流程中使用处理组件 <a class="header-anchor" href="#在流程中使用处理组件" aria-label="Permalink to &quot;在流程中使用处理组件&quot;">​</a></h2><p>在此流程中，<strong>拆分文本</strong>处理组件将传入的<a href="https://example.com/concepts-objects" target="_blank" rel="noreferrer">数据</a>拆分为块，以便嵌入到向量存储组件中。</p><p>该组件提供对块大小、重叠和分隔符的控制，这会影响到向量存储检索结果的上下文和粒度。</p><p><img src="'+o+'" alt=""></p><h2 id="更改元数据" tabindex="-1">更改元数据 <a class="header-anchor" href="#更改元数据" aria-label="Permalink to &quot;更改元数据&quot;">​</a></h2><p>该组件用于修改输入对象的元数据。它可以添加新的元数据、更新现有元数据，以及移除指定的元数据字段。该组件可以处理 <a href="./concepts-objects.html#message-object">消息</a> 和 <a href="./concepts-objects.html#data-object">数据</a> 对象，还可以根据用户提供的文本创建新的数据对象。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>input_value</td><td>Input</td><td>将添加元数据的对象</td></tr><tr><td>text_in</td><td>User Text</td><td>文本输入；值将在 <a href="./URL.html">Data</a> 对象的 &#39;text&#39; 属性中。忽略空文本输入。</td></tr><tr><td>metadata</td><td>Metadata</td><td>要添加到每个对象的元数据</td></tr><tr><td>remove_fields</td><td>Fields to Remove</td><td>要移除的元数据字段</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>输入对象的列表，每个对象附加了元数据</td></tr></tbody></table><h2 id="合并文本" tabindex="-1">合并文本 <a class="header-anchor" href="#合并文本" aria-label="Permalink to &quot;合并文本&quot;">​</a></h2><p>该组件使用指定的分隔符将两个文本源连接为一个单一的文本块。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>first_text</td><td>First Text</td><td>要连接的第一个文本输入。</td></tr><tr><td>second_text</td><td>Second Text</td><td>要连接的第二个文本输入。</td></tr><tr><td>delimiter</td><td>Delimiter</td><td>用于分隔两个文本输入的字符串。默认为一个空格。</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>message</td><td>Message</td><td>包含合并文本的 <a href="#message-object">Message</a> 对象。</td></tr></tbody></table><h2 id="创建数据" tabindex="-1">创建数据 <a class="header-anchor" href="#创建数据" aria-label="Permalink to &quot;创建数据&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>此组件为<strong>遗留</strong>组件，这意味着自 Langflow 版本 1.1.3 起，它已不再处于活跃开发中。</p></div><p>该组件动态创建一个具有指定字段数量的<a href="./URL.html">数据</a>对象。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>number_of_fields</td><td>Number of Fields</td><td>要添加到记录中的字段数量。</td></tr><tr><td>text_key</td><td>Text Key</td><td>用于标识作为文本内容的字段的键。</td></tr><tr><td>text_key_validator</td><td>Text Key Validator</td><td>如果启用，将检查所提供的 <code>Text Key</code> 是否存在于所提供的 <code>Data</code> 中。</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>根据指定字段和文本键创建的<a href="/concepts-objects#data-object">Data</a>对象。</td></tr></tbody></table><h2 id="data-combiner" tabindex="-1">Data combiner <a class="header-anchor" href="#data-combiner" aria-label="Permalink to &quot;Data combiner&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>important</p><p>在 Langflow 1.1.3 版本之前，该组件被命名为 <strong>Merge Data</strong>。</p></div><p>该组件将多个数据源组合成一个统一的<a href="https://example.com/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a>对象。</p><p>组件遍历输入的数据对象列表，将它们合并为一个数据对象。如果输入列表为空，则返回一个空的数据对象。如果只有一个输入数据对象，则返回该对象不变。合并过程使用加法运算符来结合数据对象。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>要合并的数据对象列表。</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>merged_data</td><td>Merged Data</td><td>一个单一的 <a href="https://example.com/concepts-objects#data-object" target="_blank" rel="noreferrer">Data</a> 对象，包含来自所有输入数据对象的合并信息。</td></tr></tbody></table><h2 id="dataframe-operations" tabindex="-1">DataFrame 操作 <a class="header-anchor" href="#dataframe-operations" aria-label="Permalink to &quot;DataFrame 操作 {#dataframe-operations}&quot;">​</a></h2><p>该组件对 Pandas <a href="https://pandas.pydata.org/docs/reference/api/pandas.DataFrame.html" target="_blank" rel="noreferrer">DataFrame</a> 执行以下操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>描述</th><th>必需输入</th></tr></thead><tbody><tr><td>添加列</td><td>添加一个具有常量值的新列</td><td>new_column_name, new_column_value</td></tr><tr><td>删除列</td><td>移除指定的列</td><td>column_name</td></tr><tr><td>过滤</td><td>基于列值过滤行</td><td>column_name, filter_value</td></tr><tr><td>取前几行</td><td>返回前 n 行</td><td>num_rows</td></tr><tr><td>重命名列</td><td>重命名已有的列</td><td>column_name, new_column_name</td></tr><tr><td>替换值</td><td>替换列中的值</td><td>column_name, replace_value, replacement_value</td></tr><tr><td>选择列</td><td>选择特定列</td><td>columns_to_select</td></tr><tr><td>排序</td><td>按照列对 DataFrame 进行排序</td><td>column_name, ascending</td></tr><tr><td>取后几行</td><td>返回后 n 行</td><td>num_rows</td></tr></tbody></table><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>df</td><td>DataFrame</td><td>要操作的输入 DataFrame。</td></tr><tr><td>operation</td><td>Operation</td><td>选择要执行的 DataFrame 操作。选项：添加列、删除列、过滤、头部、重命名列、替换值、选择列、排序、尾部。</td></tr><tr><td>column_name</td><td>Column Name</td><td>用于操作的列名称。</td></tr><tr><td>filter_value</td><td>Filter Value</td><td>用于筛选行的值。</td></tr><tr><td>ascending</td><td>Sort Ascending</td><td>是否按升序排序。</td></tr><tr><td>new_column_name</td><td>New Column Name</td><td>重命名或添加列时的新列名称。</td></tr><tr><td>new_column_value</td><td>New Column Value</td><td>用于填充新列的值。</td></tr><tr><td>columns_to_select</td><td>Columns to Select</td><td>要选择的列名称列表。</td></tr><tr><td>num_rows</td><td>Number of Rows</td><td>返回的行数（用于头部/尾部）。默认值：5</td></tr><tr><td>replace_value</td><td>Value to Replace</td><td>要在列中替换的值。</td></tr><tr><td>replacement_value</td><td>Replacement Value</td><td>用于替换的值。</td></tr></tbody></table><h3 id="outputs-3" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-3" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>output</td><td>DataFrame</td><td>操作后的结果DataFrame。</td></tr></tbody></table><h2 id="data-to-message" tabindex="-1">Data to message <a class="header-anchor" href="#data-to-message" aria-label="Permalink to &quot;Data to message&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">important</p><p>在 Langflow 1.1.3 版本之前，该组件被命名为 <strong>解析数据</strong>。</p></div><p><code>ParseData</code> 组件使用指定的模板将数据对象转换为纯文本。该组件将结构化数据转换为易读的文本格式，并通过使用模板实现可定制的输出。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>要转换为文本的数据。</td></tr><tr><td>template</td><td>Template</td><td>用于格式化数据的模板。它可以包含键 <code>&lt;code&gt;{text}&lt;/code&gt;</code>，<code>&lt;code&gt;{data}&lt;/code&gt;</code>或数据中的任何其他键。</td></tr><tr><td>sep</td><td>Separator</td><td>多个数据项之间使用的分隔符。</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>信息</th></tr></thead><tbody><tr><td>text</td><td>Text</td><td>结果格式化的文本字符串，作为一个 <a href="https://your-domain/concepts-objects#message-object" target="_blank" rel="noreferrer">Message</a> 对象。</td></tr></tbody></table><h2 id="filter-data" tabindex="-1">筛选数据 <a class="header-anchor" href="#filter-data" aria-label="Permalink to &quot;筛选数据 {#filter-data}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">important</p><p>此组件在 Langflow 版本 1.1.3 中处于 <strong>Beta</strong> 测试阶段，尚未完全支持。</p></div><p>此组件根据一系列键值来筛选一个 <a href="./URL.html">数据</a> 对象。</p><h3 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>要过滤的数据对象。</td></tr><tr><td>filter_criteria</td><td>Filter Criteria</td><td>要用于过滤的键列表。</td></tr></tbody></table><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>filtered_data</td><td>Filtered Data</td><td>新的<a href="https://vitepress.vuejs.org/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a>对象，其中仅包含符合过滤条件的键值对。</td></tr></tbody></table><h2 id="过滤值" tabindex="-1">过滤值 <a class="header-anchor" href="#过滤值" aria-label="Permalink to &quot;过滤值&quot;">​</a></h2><blockquote><p><strong>重要</strong></p><p>这个组件在 Langflow 版本 1.1.3 中处于 <strong>Beta</strong>（测试）阶段，目前尚未完全支持。</p></blockquote><p><code>Filter values</code> 组件根据指定的键、过滤值和比较运算符过滤数据项列表。</p><h3 id="inputs-5" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-5" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>input_data</td><td>Input data</td><td>要过滤的数据项列表。</td></tr><tr><td>filter_key</td><td>Filter Key</td><td>用于过滤的键，例如 &#39;route&#39;。</td></tr><tr><td>filter_value</td><td>Filter Value</td><td>用于过滤的值，例如 &#39;CMIP&#39;。</td></tr><tr><td>operator</td><td>Comparison Operator</td><td>用于比较值的运算符。</td></tr></tbody></table><h3 id="outputs-4" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-4" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>filtered_data</td><td>Filtered data</td><td>过滤后的数据项列表。</td></tr></tbody></table><h2 id="json-cleaner" tabindex="-1">JSON cleaner <a class="header-anchor" href="#json-cleaner" aria-label="Permalink to &quot;JSON cleaner&quot;">​</a></h2><p>JSON cleaner 组件用于清理 JSON 字符串，以确保它们完全符合 JSON 规范。</p><h3 id="输入项" tabindex="-1">输入项 <a class="header-anchor" href="#输入项" aria-label="Permalink to &quot;输入项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>json_str</td><td>JSON 字符串</td><td>要清理的 JSON 字符串。此字符串可以是语言模型或其他来源生成的原始的、可能格式不正确的 JSON 字符串，不一定完全符合 JSON 规范。</td></tr><tr><td>remove_control_chars</td><td>移除控制字符</td><td>如果设置为 True，则会从 JSON 字符串中移除控制字符（ASCII 字符 0-31 和 127）。这可以帮助消除可能导致解析问题或使 JSON 无效的不可见字符。</td></tr><tr><td>normalize_unicode</td><td>规范化 Unicode</td><td>当启用时，该选项会将 JSON 字符串中的 Unicode 字符标准化为其规范组合形式（NFC）。这可确保在不同系统中一致地表示 Unicode 字符，并防止字符编码潜在问题。</td></tr><tr><td>validate_json</td><td>验证 JSON</td><td>如果设置为 True，此选项将尝试解析 JSON 字符串以确保其格式良好，然后再应用最终的修复操作。如果 JSON 无效，则会引发 ValueError，从而允许及早检测 JSON 的主要结构问题。</td></tr></tbody></table><h3 id="outputs-5" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-5" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>output</td><td>Cleaned JSON String</td><td>结果为一个经过清理、修复和验证的 JSON 字符串，完全符合 JSON 规范。</td></tr></tbody></table><h2 id="llm-路由器" tabindex="-1">LLM 路由器 <a class="header-anchor" href="#llm-路由器" aria-label="Permalink to &quot;LLM 路由器&quot;">​</a></h2><p>该组件根据 OpenRouter 模型规范，将请求路由到最合适的 LLM（大语言模型）。</p><h3 id="inputs-6" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-6" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">名称</th><th style="text-align:left;">显示名称</th><th style="text-align:left;">信息</th></tr></thead><tbody><tr><td style="text-align:left;">models</td><td style="text-align:left;">Language Models</td><td style="text-align:left;">要在其间进行路由的 LLMs（大语言模型）列表</td></tr><tr><td style="text-align:left;">input_value</td><td style="text-align:left;">输入</td><td style="text-align:left;">要路由的输入消息</td></tr><tr><td style="text-align:left;">judge_llm</td><td style="text-align:left;">Judge LLM</td><td style="text-align:left;">评估并选择最合适模型的 LLM</td></tr><tr><td style="text-align:left;">optimization</td><td style="text-align:left;">优化</td><td style="text-align:left;">优化偏好（质量/速度/成本/平衡）</td></tr></tbody></table><h3 id="输出-3" tabindex="-1">输出 <a class="header-anchor" href="#输出-3" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>output</td><td>Output</td><td>来自所选模型的响应</td></tr><tr><td>selected_model</td><td>Selected Model</td><td>选择的模型名称</td></tr></tbody></table><h2 id="消息到数据" tabindex="-1">消息到数据 <a class="header-anchor" href="#消息到数据" aria-label="Permalink to &quot;消息到数据&quot;">​</a></h2><p>该组件将<a href="./链接到概念对象.html#消息对象">消息</a>对象转换为<a href="./链接到概念对象.html#数据对象">数据</a>对象。</p><h3 id="inputs-7" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-7" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>message</td><td>Message</td><td>要转换为 <a href="https://example.com/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a> 对象的 <a href="https://example.com/concepts-objects#message-object" target="_blank" rel="noreferrer">消息</a> 对象。</td></tr></tbody></table><h3 id="outputs-6" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-6" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>转换后的 <a href="./链接到/概念-对象.html#data-对象">Data</a> 对象。</td></tr></tbody></table><h2 id="解析-dataframe" tabindex="-1">解析 DataFrame <a class="header-anchor" href="#解析-dataframe" aria-label="Permalink to &quot;解析 DataFrame&quot;">​</a></h2><p>该组件使用模板将 DataFrame 转换为纯文本。</p><h3 id="inputs-8" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-8" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>df</td><td>DataFrame</td><td>要转换为文本行的 DataFrame</td></tr><tr><td>template</td><td>模板</td><td>用于格式化的模板（使用 <code>{column_name}</code> 占位符）</td></tr><tr><td>sep</td><td>分隔符</td><td>用于在输出中连接行的字符串</td></tr></tbody></table><h3 id="outputs-7" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-7" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>text</td><td>Text</td><td>所有行合并为单一文本</td></tr></tbody></table><h2 id="解析-json" tabindex="-1">解析 JSON <a class="header-anchor" href="#解析-json" aria-label="Permalink to &quot;解析 JSON&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">重要</p><p>此组件处于<strong>遗留</strong>状态，这意味着从 Langflow 版本 1.1.3 开始，不再进行主动开发。</p></div><p>这个组件使用 JQ 查询来转换和提取 JSON 字段。</p><h3 id="inputs-9" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-9" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>input_value</td><td>输入</td><td>要过滤的数据对象（<a href="//concepts-objects#message-object" target="_blank" rel="noreferrer">消息</a> 或 <a href="//concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a>）。</td></tr><tr><td>query</td><td>JQ 查询</td><td>用于过滤数据的 JQ 查询</td></tr></tbody></table><h3 id="outputs-12" tabindex="-1">输出 <a class="header-anchor" href="#outputs-12" aria-label="Permalink to &quot;输出 {#outputs-12}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>filtered_data</td><td>Filtered Data</td><td>作为 <a href="/concepts-objects#data-object">Data</a> 对象列表的过滤数据。</td></tr></tbody></table><h2 id="选择数据" tabindex="-1">选择数据 <a class="header-anchor" href="#选择数据" aria-label="Permalink to &quot;选择数据&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>重要</p><p>该组件属于<strong>遗留</strong>（Legacy）组件，这意味着自 Langflow 版本 1.1.3 起，它不再处于活跃开发状态。</p></div><p>该组件从列表中选择单个<a href="./URL.html">数据</a>项。</p><h3 id="输入-2" tabindex="-1">输入 <a class="header-anchor" href="#输入-2" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data_list</td><td>Data List</td><td>可供选择的数据列表</td></tr><tr><td>data_index</td><td>Data Index</td><td>要选择的数据的索引</td></tr></tbody></table><h3 id="输出-4" tabindex="-1">输出 <a class="header-anchor" href="#输出-4" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>selected_data</td><td>选定数据</td><td>选定的 <a href="https://yourwebsite.com/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a> 对象。</td></tr></tbody></table><h2 id="分割文本" tabindex="-1">分割文本 <a class="header-anchor" href="#分割文本" aria-label="Permalink to &quot;分割文本&quot;">​</a></h2><p>该组件根据指定的条件将文本分割成多个块。</p><h3 id="inputs-10" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-10" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data_inputs</td><td>Data Inputs</td><td>要拆分的数据</td></tr><tr><td>chunk_overlap</td><td>Chunk Overlap</td><td>块之间重叠的字符数</td></tr><tr><td>chunk_size</td><td>Chunk Size</td><td>每个块中的最大字符数</td></tr><tr><td>separator</td><td>Separator</td><td>拆分字符（默认为换行符）</td></tr></tbody></table><h3 id="输出-5" tabindex="-1">输出 <a class="header-anchor" href="#输出-5" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>chunks</td><td>Chunks</td><td>作为 <a href="https://example.com/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a> 对象的分割文本块列表。</td></tr><tr><td>dataframe</td><td>DataFrame</td><td>以 DataFrame 形式表示的文本块</td></tr></tbody></table><h2 id="更新数据" tabindex="-1">更新数据 <a class="header-anchor" href="#更新数据" aria-label="Permalink to &quot;更新数据&quot;">​</a></h2><p>该组件动态更新或追加具有指定字段的数据。</p><h3 id="inputs-11" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-11" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>old_data</td><td>Data</td><td>需要更新的记录</td></tr><tr><td>number_of_fields</td><td>Number of Fields</td><td>需要添加的字段数量（最多 15 个）</td></tr><tr><td>text_key</td><td>Text Key</td><td>文本内容的键</td></tr><tr><td>text_key_validator</td><td>Text Key Validator</td><td>验证文本键的存在性</td></tr></tbody></table><h3 id="outputs-8" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-8" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>更新的 <a href="https://example.com/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a> 对象。</td></tr></tbody></table>',111)]))}const m=a(h,[["render",l]]);export{p as __pageData,m as default};
